import {LAYOUTS,layoutId,switchLayout} from './practice-layout.js';
import {GRADES,MODES,CONFIG,generateQuestions,gradeQuestions,formatTime} from './math.js';
import {storage,loadHistory,loadSession} from './storage.js';
import {createCardUI} from './card-ui.js';
import {SKINS,PETS,appearance,petId,growthFromHistory,roundGrowth} from './companions.js';
import {createHabitatUI} from './habitat-ui.js';
import {normalizeHabitat,coinRewards} from './habitat.js';
import {companionArt} from './companion-art.js';
import {COMPANION_ART} from './companion-art-data.js';
let outfit=appearance(storage.read('appearance',{}));
function saveOutfit(){storage.write('appearance',outfit);}
function applySkin(){const theme=SKINS[outfit.skin];document.documentElement.dataset.skin=outfit.skin;for(const [key,value] of Object.entries({teal:theme.main,'teal-dark':theme.dark,mint:theme.tint,paper:theme.paper,ink:theme.ink,muted:theme.muted,line:theme.line}))document.documentElement.style.setProperty('--'+key,value);document.querySelector('meta[name=theme-color]').content=theme.main;}
applySkin();
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const prefs=storage.read('prefs',{});
let grade=[1,2,3,4,5,6].includes(prefs?.grade)?prefs.grade:2,mode=['mixed','addsub','multiply','missing'].includes(prefs?.mode)?prefs.mode:'mixed',count=[20,30,60].includes(prefs?.count)?prefs.count:60;
let layout=layoutId(prefs?.layout);
if(grade===1&&mode==='multiply')mode='mixed';
let explorerName=typeof prefs?.name==='string'?prefs.name.slice(0,12):'',sound=prefs?.sound!==false,session=loadSession(),view='home',clock=0,result=null,showAll=false,activeIndex=0,historyGrade='all';
const cardUI=createCardUI({app,modal,storage,history:loadHistory,getView:()=>view,renderResult,go,toast,chime,confetti});
const habitatUI=createHabitatUI({app,modal,storage,history:loadHistory,getOutfit:()=>outfit,setOutfit:value=>{outfit=value;saveOutfit();applySkin();},practice:()=>session?resumePractice():go('home'),toast,chime});
const escapeHtml=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const displayMode=(m,g=grade)=>g===2&&m==='multiply'?'乘除口诀':MODES[m]||'综合探险';
function savePrefs(){storage.write('prefs',{grade,mode,count,layout,name:explorerName,sound});}
function toast(message){const box=document.querySelector('#toast');box.textContent=message;box.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.classList.remove('show'),3500);}
window.addEventListener('storage-failed',()=>toast('浏览器暂时无法保存记录。请下载成绩图片留存。'));
function confirmDialog(title,message,label,callback){pauseClock();document.querySelector('#modal-content').innerHTML=`<h2>${title}</h2><p>${message}</p><div class="dialog-actions"><button class="secondary" id="cancel-dialog">再想想</button><button class="primary" id="confirm-dialog">${label}</button></div>`;modal.showModal();document.querySelector('#cancel-dialog').onclick=()=>modal.close();document.querySelector('#confirm-dialog').onclick=()=>{modal.close();callback();};}
modal.addEventListener('close',()=>{if(view==='practice'&&session&&session.paused){resumeClock();renderPractice();}});
let audio;
function chime(success=false){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});const now=audio.currentTime;(success?[523,659,784,1046]:[523,659]).forEach((f,i)=>{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(0,now+i*.12);gain.gain.linearRampToValueAtTime(.06,now+i*.12+.015);gain.gain.exponentialRampToValueAtTime(.001,now+i*.12+.22);osc.connect(gain);gain.connect(audio.destination);osc.start(now+i*.12);osc.stop(now+i*.12+.24);});}catch{}}
function updateSound(){document.querySelector('#sound-toggle').setAttribute('aria-pressed',String(sound));document.querySelector('#sound-toggle').setAttribute('aria-label',sound?'关闭音效':'开启音效');document.querySelector('#sound-icon').textContent=sound?'♫':'♪';document.querySelector('.sound-label').textContent=sound?'音效开启':'音效关闭';}
document.querySelector('#sound-toggle').onclick=()=>{sound=!sound;savePrefs();updateSound();if(sound)chime();};
function elapsed(){return session?session.elapsed+(session.paused?0:performance.now()-clock):0;}
function checkpoint(){if(!session)return;session.elapsed=elapsed();clock=performance.now();storage.write('session',session);}
function pauseClock(){if(session&&!session.paused){checkpoint();session.paused=true;storage.write('session',session);}}
function resumeClock(){if(session){session.paused=false;clock=performance.now();storage.write('session',session);}}
function go(next){if(view==='practice')pauseClock();view=next;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===next));if(next==='home')renderHome();else if(next==='history')renderHistory();else if(next==='mistakes')renderMistakes();else if(next==='pets'){renderPets();}else if(next==='cards')cardUI.render();window.scrollTo({top:0,behavior:'instant'});app.focus({preventScroll:true});}
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));document.querySelector('.brand').onclick=e=>{e.preventDefault();go('home');};
function startPractice(questions=null,reviewGrade=grade){const begin=()=>{const qs=questions||generateQuestions({grade,mode,count});session={id:crypto.randomUUID(),petId:outfit.pet,grade:questions?reviewGrade:grade,mode:questions?'review':mode,name:explorerName.trim()||'小小探险家',questions:qs.map((q,i)=>({...q,id:`q-${i+1}`})),answers:qs.map(()=>''),layout,page:0,elapsed:0,paused:false};clock=performance.now();checkpoint();view='practice';document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav==='home'));renderPractice();window.scrollTo({top:0,behavior:'instant'});chime();};if(session)confirmDialog('开启新的探险？','当前未完成的探险会被替换。你也可以先回到首页继续上次练习。','开始新一轮',begin);else begin();}
function resumePractice(){view='practice';document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav==='home'));resumeClock();renderPractice();window.scrollTo({top:0,behavior:'instant'});}
function renderHome(){const history=loadHistory();const answered=history.reduce((n,r)=>n+r.total,0);const stars=history.reduce((n,r)=>n+r.stars,0);const guide=grade===2&&mode==='multiply'?{topics:['1–9 的乘法口诀','约四分之一为口诀整除题','用乘法口诀，想出商'],samples:['7 × 8 = □','56 ÷ 7 = □','4 × 5 = □']}:CONFIG[grade];app.innerHTML=`${session?`<div class="resume-banner"><div><strong>还有一段探险，等你继续</strong><small>${GRADES[session.grade-1]}年级${session.layout&&session.layout!=='sheet'?' · '+LAYOUTS[layoutId(session.layout)].name:''} · 已填 ${session.answers.filter(a=>a.trim()).length}/${session.questions.length} 题 · 用时 ${formatTime(session.elapsed)}</small></div><div class="resume-actions"><button id="discard" class="text-btn">重新准备</button><button id="resume" class="secondary">继续上次探险</button></div></div>`:''}<section class="hero"><div class="hero-copy"><div class="small-label">✦ 小小探险家，准备好了吗？</div><h1>把每一道口算，<br>变成一次<em>小探险。</em></h1><p>和${PETS[outfit.pet].name}一起出发，答对一题获得 1 成长积分。<br>不着急，认真算，每一步都算进步。</p><div class="hero-start"><button id="quick-start" class="primary">开始 ${count} 题探险</button><span>${GRADES[grade-1]}年级 · ${displayMode(mode)}</span></div></div>${homeCompanion()}</section><div class="content-grid"><section class="panel"><div class="panel-heading"><h2>准备你的探险</h2><span>选好难度，马上出发</span></div><div class="step-label"><span class="step-number">1</span>你在几年级？</div><div class="grade-grid">${GRADES.map((g,i)=>`<button class="grade-btn ${grade===i+1?'active':''}" data-grade="${i+1}" aria-pressed="${grade===i+1}"><strong>${g}</strong>年级</button>`).join('')}</div><div class="step-label"><span class="step-number">2</span>今天想挑战什么？</div><div class="mode-grid">${[['mixed','✦','综合探险','多种题型，一起挑战'],['addsub','±','加减训练','和加减法交朋友'],['multiply','×',grade===2?'乘除口诀':'乘除训练',grade===1?'二年级开启':grade===2?'乘法为主，少量除法':'把口诀练得更熟'],['missing','?','填空挑战','寻找消失的数字']].map(([m,ic,t,d])=>`<button class="mode-btn ${mode===m?'active':''}" data-mode="${m}" ${grade===1&&m==='multiply'?'disabled':''} aria-pressed="${mode===m}"><span class="mode-icon">${ic}</span><span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div><div class="step-label"><span class="step-number">3</span>想怎么练习？</div>${layoutChoices(layout,'data-home-layout')}<div class="choice-line"><div><div class="step-label"><span class="step-number">4</span>这一轮，走多远？</div><div class="count-group">${[20,30,60].map(n=>`<button class="count-btn ${count===n?'active':''}" data-count="${n}">${n} 题${n===60?' · 标准':''}</button>`).join('')}</div></div><label class="name-field">探险家<input id="name" value="${escapeHtml(explorerName)}" maxlength="12" placeholder="小小探险家" aria-label="探险家名字"></label></div><div class="start-row"><p>${layout==='single'?'大字单题 · 按 Enter 继续':'每次 10 题 · 完成后自动批改'}<br>60 题，对应练习册正反面</p><button id="start" class="primary">开启今日探险</button></div></section><aside class="side-panel"><div class="eyebrow"><span></span> EXPLORER'S GUIDE</div><h3 class="handbook-title">${GRADES[grade-1]}年级 · 探险手册</h3><ul class="topic-list">${guide.topics.map(t=>`<li>${t}</li>`).join('')}</ul><div class="sample"><div class="sample-label">你会遇到这样的题目</div>${guide.samples.join('<br>')}</div><div class="tip"><span class="tip-icon">✧</span><p>算得慢一点也没关系，<br>想清楚，比抢着答更棒。</p></div></aside></div><section class="stats-strip" aria-label="我的探险数据"><div class="stat-box"><div class="stat-symbol">⚑</div><div><strong>${history.length} 次探险</strong><span>每一次出发都值得记录</span></div></div><div class="stat-box"><div class="stat-symbol">✓</div><div><strong>${answered} 道口算</strong><span>让进步一点一点积累</span></div></div><div class="stat-box"><div class="stat-symbol">✦</div><div><strong>${stars?stars+' 颗星星':'等你点亮'}</strong><span>完成探险，收集星星</span></div></div></section>`;app.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{grade=+b.dataset.grade;if(grade===1&&mode==='multiply')mode='mixed';savePrefs();renderHome()});app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;savePrefs();renderHome()});app.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{count=+b.dataset.count;savePrefs();renderHome()});app.querySelectorAll('[data-home-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.homeLayout;savePrefs();renderHome();});document.querySelector('#name').oninput=e=>{explorerName=e.target.value;savePrefs();};document.querySelector('#start').onclick=()=>startPractice();document.querySelector('#quick-start').onclick=()=>startPractice();document.querySelector('#home-pet').onclick=()=>go('pets');if(session){document.querySelector('#resume').onclick=()=>resumePractice();document.querySelector('#discard').onclick=()=>confirmDialog('重新准备探险？','会放下这轮尚未完成的题目，已完成的历史记录会保留。','重新准备',()=>{session=null;storage.remove('session');renderHome();});}}
function petArt(id,level,extra=''){const state=normalizeHabitat(storage.read('habitat',{}),loadHistory());return companionArt(id,level,state.outfits[petId(id)],extra);}
function homeCompanion(){const p=growthFromHistory(loadHistory())[outfit.pet];return `<div class="hero-companion">${petArt(outfit.pet,p.level)}<button id="home-pet" class="hero-pet-label"><strong>${PETS[outfit.pet].name} · Lv.${p.level}</strong><span>${p.points} 成长积分 · 回伙伴小屋</span></button></div>`;}
function rewardCard(r){if(!r.growth)return '<p class="legacy-growth">早期练习的正确答案已计入小狐狸的成长积分。</p>';const g=r.growth,id=petId(r.petId);return `<section class="pet-reward ${g.leveledUp?'level-up':''}" aria-label="本轮伙伴成长">${petArt(id,g.level)}<div><span class="eyebrow">${g.leveledUp?'✦ 伙伴升级啦！':'✦ 一起进步'}</span><h2>${PETS[id].name}获得 ${g.earned} 成长积分</h2><p>${g.leveledUp?`从 Lv.${g.beforeLevel} 升到 Lv.${g.level} · `:''}${PETS[id].stages[g.level-1]} · 累计 ${g.points} 分</p></div><button id="reward-pets" class="secondary">去伙伴小屋</button></section>`;}
function renderPets(){habitatUI.render();}
function coinReward(r){const reward=coinRewards(loadHistory()).find(x=>x.id===r.id);if(!reward?.total)return '';return `<section class="coin-reward"><div><h2><span class="leaf-coin">❧</span> 这次探险收获 ${reward.total} 叶子币</h2><p>认真填答 +${reward.base}${reward.completion?' · 完成奖励 +10':''}${reward.daily?' · 今日首轮 +10':''} · 去为伙伴挑一件喜欢的好物吧</p></div><button id="reward-home" class="secondary">去装扮小屋</button></section>`;}
function celebratePet(id){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const pet=PETS[id],box=document.createElement('div');box.className=`pet-celebration celebration-${id}`;box.setAttribute('aria-hidden','true');box.style.setProperty('--pet-accent',pet.accent);box.innerHTML=Array.from({length:16},(_,i)=>`<span style="--i:${i};--x:${15+Math.random()*70}%">${pet.spark}</span>`).join('');document.body.append(box);setTimeout(()=>box.remove(),2600);}

const stationNames=['启程草地','数字小桥','口诀森林','思考山谷','星光营地','宝藏终点'];
function layoutChoices(selected,attribute){return `<div class="layout-choices" aria-label="练习方式">${Object.entries(LAYOUTS).map(([id,l])=>`<button class="layout-choice ${selected===id?'active':''}" ${attribute}="${id}" aria-pressed="${selected===id}"><strong>${l.name}</strong><small>${l.description}</small></button>`).join('')}</div>`;}
function renderPractice(){
 if(layoutId(session.layout)==='single'){renderSinglePractice();return;}
 const total=session.questions.length,pages=Math.ceil(total/10),start=session.page*10,filled=session.answers.filter(a=>a.trim()).length;
 app.innerHTML=`<section class="practice-head"><div><div class="eyebrow"><span></span> LITTLE STEPS, BIG ADVENTURES</div><h1>${GRADES[session.grade-1]}年级 · ${displayMode(session.mode,session.grade)}</h1><p>${escapeHtml(session.name)}，想清楚再写答案。每完成 10 题，就前进一站。</p>${layoutChoices('sheet','data-practice-layout')}</div><div class="timer-panel"><span>探险用时</span><strong id="timer">${formatTime(elapsed())}</strong><button id="pause" class="text-btn">${session.paused?'继续练习':'Ⅱ 暂停一下'}</button></div></section><section class="trail-panel"><div class="trail-heading"><strong>你的探险路线</strong><span id="filled-text">已填 ${filled} / ${total} 题</span></div><div class="trail" role="navigation" aria-label="题目分组">${Array.from({length:pages},(_,i)=>{const complete=session.answers.slice(i*10,(i+1)*10).filter(a=>a.trim()).length===Math.min(10,total-i*10);return `<button class="station ${i===session.page?'current':''} ${complete?'complete':''}" data-page="${i}" aria-label="第 ${i+1} 站" ${i===session.page?'aria-current="step"':''}><span class="station-circle">${complete?'✓':i+1}</span><span class="station-name">${stationNames[i]||'探险站'}</span></button>`;}).join('')}</div><div class="progress-track"><div id="answer-progress" style="width:${filled/total*100}%"></div></div></section><section class="worksheet panel"><div class="panel-heading"><h2>第 ${session.page+1} 站 · ${stationNames[session.page]||'探险站'}</h2><span>第 ${start+1}–${Math.min(start+10,total)} 题 / 共 ${total} 题</span></div><div class="question-grid">${session.questions.slice(start,start+10).map((q,j)=>{const i=start+j,parts=q.expression.split('□');return `<div class="question-row ${session.answers[i]?'answered':''}" id="row-${i}"><span class="question-number">${String(i+1).padStart(2,'0')}</span><label class="equation" for="answer-${i}"><span>${escapeHtml(parts[0])}</span><input id="answer-${i}" class="answer-input" data-index="${i}" type="text" inputmode="${session.grade>=5?'decimal':'numeric'}" autocomplete="off" maxlength="8" aria-label="第 ${i+1} 题：${escapeHtml(q.expression)}" value="${escapeHtml(session.answers[i])}" ${session.paused?'disabled':''}><span>${escapeHtml(parts[1])}</span></label></div>`;}).join('')}</div><div class="worksheet-foot"><span>小提示：按 Enter 可以跳到下一题 · 方框里只填答案</span><div><button id="prev-page" class="secondary" ${session.page===0?'disabled':''}>上一站</button><button id="next-page" class="primary">${session.page===pages-1?'完成探险，交卷':'完成这站，继续'}</button></div></div>${session.paused?'<div class="pause-overlay"><span class="pause-symbol">Ⅱ</span><h2>休息一下，探险在这里等你</h2><p>计时已暂停，答案已保存。</p><button id="resume-overlay" class="primary">继续探险</button><button id="pause-home" class="text-btn">回到首页</button></div>':''}</section><p class="practice-note">✧ 不比速度，只和昨天的自己比。每一题认真思考就很棒。</p><p class="round-partner">本轮伙伴：${PETS[petId(session.petId)].name} · 交卷后，答对的题目会变成成长积分。</p>`;
 bindPracticeLayout();app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>changePage(+b.dataset.page));
 document.querySelector('#pause').onclick=()=>{if(session.paused)resumeClock();else pauseClock();renderPractice();};
 if(session.paused){document.querySelector('#resume-overlay').onclick=()=>{resumeClock();renderPractice();};document.querySelector('#pause-home').onclick=()=>go('home');}
 app.querySelectorAll('.answer-input').forEach(input=>{
  input.onfocus=()=>{activeIndex=+input.dataset.index;};
  input.oninput=()=>saveAnswer(input);
  input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const idx=+input.dataset.index;if(idx+1<Math.min(start+10,total))document.querySelector(`#answer-${idx+1}`).focus();else document.querySelector('#next-page').focus();}};
 });
 document.querySelector('#prev-page').onclick=()=>changePage(session.page-1);document.querySelector('#next-page').onclick=()=>session.page===pages-1?requestSubmit():nextPage();
}
function bindPracticeLayout(){app.querySelectorAll('[data-practice-layout]').forEach(b=>b.onclick=()=>{session=switchLayout(session,b.dataset.practiceLayout,activeIndex);layout=session.layout;savePrefs();checkpoint();renderPractice();});}
function saveAnswer(input){
 let value=input.value.replace(/[^\d.]/g,'');const dot=value.indexOf('.');if(dot>=0)value=value.slice(0,dot+1)+value.slice(dot+1).replace(/\./g,'');if(session.grade<5)value=value.replace(/\./g,'');input.value=value;input.style.setProperty('--answer-chars',Math.max(2,value.length));session.answers[+input.dataset.index]=value;document.querySelector(`#row-${input.dataset.index}`)?.classList.toggle('answered',!!value);checkpoint();updateProgress();
}
function renderSinglePractice(){
 const total=session.questions.length,index=session.page,q=session.questions[index],parts=q.expression.split('□'),filled=session.answers.filter(a=>a.trim()).length;
 app.innerHTML=`<section class="practice-head single-head"><div><div class="eyebrow"><span></span> ONE QUESTION, ONE LITTLE STEP</div><h1>单题闯关 <small>· ${GRADES[session.grade-1]}年级 · ${displayMode(session.mode,session.grade)}</small></h1><p>一次只看一道题，想清楚，再向前一步。</p>${layoutChoices('single','data-practice-layout')}</div><div class="timer-panel"><span>探险用时</span><strong id="timer">${formatTime(elapsed())}</strong><button id="pause" class="text-btn">${session.paused?'继续练习':'Ⅱ 暂停一下'}</button></div></section><section class="single-progress panel"><strong>第 ${index+1} / ${total} 题</strong><span id="filled-text">已填 ${filled} / ${total} 题</span><div class="progress-track"><div id="answer-progress" style="width:${filled/total*100}%"></div></div></section><section class="single-worksheet worksheet panel"><div class="single-question-heading"><span>✦ 每认真完成一题，就前进一步</span><strong>${q.kind==='missing'?'寻找消失的数字':'算一算，答案是多少？'}</strong></div><div class="single-question ${session.answers[index]?'answered':''}" id="row-${index}"><label class="single-equation equation" for="answer-${index}"><span>${escapeHtml(parts[0])}</span><input id="answer-${index}" class="answer-input" style="--answer-chars:${Math.max(2,session.answers[index].length)}" data-index="${index}" type="text" inputmode="${session.grade>=5?'decimal':'numeric'}" autocomplete="off" maxlength="8" aria-label="第 ${index+1} 题：${escapeHtml(q.expression)}" value="${escapeHtml(session.answers[index])}" ${session.paused?'disabled':''}><span>${escapeHtml(parts[1])}</span></label></div><p class="single-input-help">在方框里填答案 · 按 Enter ${index===total-1?'交卷':'进入下一题'}</p><div class="single-actions"><button id="single-prev" class="secondary" ${index===0?'disabled':''}>上一题</button><button id="single-next" class="primary">${index===total-1?'完成闯关，交卷':'下一题 →'}</button></div><button id="single-skip" class="text-btn">${index===total-1?'跳过这题并交卷':'先跳过，稍后再算'}</button>${session.paused?'<div class="pause-overlay"><span class="pause-symbol">Ⅱ</span><h2>休息一下，探险在这里等你</h2><p>计时已暂停，答案已保存。</p><button id="resume-overlay" class="primary">继续探险</button><button id="pause-home" class="text-btn">回到首页</button></div>':''}</section><details class="single-map panel"><summary>题目地图 <span>回头检查，也是一种好习惯</span></summary><div class="single-map-grid" aria-label="选择要检查的题目">${session.questions.map((_,i)=>`<button data-question="${i}" class="${i===index?'current':''} ${session.answers[i].trim()?'filled':''}" aria-label="第 ${i+1} 题，${session.answers[i].trim()?'已填写':'未填写'}" ${i===index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p>有颜色的题目已经填写，交卷后统一批改。</p></details><p class="round-partner">本轮伙伴：${PETS[petId(session.petId)].name} · 完成后可以抽一张卡。</p>`;
 bindPracticeLayout();const input=app.querySelector('.answer-input');input.onfocus=()=>{activeIndex=index;};input.oninput=()=>saveAnswer(input);input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();nextSingle();}};
 app.querySelector('#single-next').onclick=()=>nextSingle();app.querySelector('#single-skip').onclick=()=>nextSingle(true);app.querySelector('#single-prev').onclick=()=>changeSingle(index-1);
 app.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>changeSingle(+b.dataset.question));
 app.querySelector('#pause').onclick=()=>{if(session.paused)resumeClock();else pauseClock();renderPractice();};
 if(session.paused){app.querySelector('#resume-overlay').onclick=()=>{resumeClock();renderPractice();};app.querySelector('#pause-home').onclick=()=>go('home');}
}
function updateSingleProgress(){
 const filled=session.answers.filter(a=>a.trim()).length;app.querySelector('#filled-text').textContent=`已填 ${filled} / ${session.questions.length} 题`;app.querySelector('#answer-progress').style.width=`${filled/session.questions.length*100}%`;
 const button=app.querySelector(`[data-question="${session.page}"]`),answered=!!session.answers[session.page].trim();button.classList.toggle('filled',answered);button.setAttribute('aria-label',`第 ${session.page+1} 题，${answered?'已填写':'未填写'}`);
}
function changeSingle(index){
 if(!Number.isInteger(index)||index<0||index>=session.questions.length)return;session.page=index;activeIndex=index;checkpoint();renderPractice();app.querySelector('.answer-input')?.focus({preventScroll:true});
}
function nextSingle(skip=false){
 if(session.paused)return;if(!skip&&!session.answers[session.page].trim()){toast('先写下你的答案，或者点“先跳过”稍后再算。');app.querySelector('.answer-input')?.focus();return;}
 if(session.page===session.questions.length-1){requestSubmit();return;}
 if(!skip&&((session.page+1)%10===0))chime();changeSingle(session.page+1);
}

function updateProgress(){if(session.layout==='single'){updateSingleProgress();return;}const filled=session.answers.filter(a=>a.trim()).length;document.querySelector('#filled-text').textContent=`已填 ${filled} / ${session.questions.length} 题`;document.querySelector('#answer-progress').style.width=`${filled/session.questions.length*100}%`;const current=document.querySelector('.station.current');const complete=session.answers.slice(session.page*10,(session.page+1)*10).every(a=>a.trim());current.classList.toggle('complete',complete);current.querySelector('.station-circle').textContent=complete?'✓':session.page+1;}
function changePage(page){session.page=page;checkpoint();renderPractice();document.querySelector('.worksheet').scrollIntoView({behavior:'instant',block:'nearest'});}
function nextPage(){const remaining=session.answers.slice(session.page*10,(session.page+1)*10).filter(a=>!a.trim()).length;if(remaining){toast(`这站还有 ${remaining} 题没填，之后也可以回来补上。`);}else{chime();toast(pickEncouragement());}changePage(session.page+1);}
function pickEncouragement(){return ['又前进了一站，继续加油！','认真思考的小探险家，真棒！','新的风景就在下一站！'][Math.floor(Math.random()*3)];}
function requestSubmit(){const blanks=session.answers.filter(a=>!a.trim()).length;confirmDialog(blanks?`还有 ${blanks} 题没有填答案`:'准备好结束这次探险了吗？',blanks?'空着的题目会计入未答题，也会放进错题背包。你可以返回继续检查。':'现在可以检查一下，交卷后就能看到成绩和解题提示。','交卷并批改',finishPractice);}
function finishPractice(){pauseClock();const graded=gradeQuestions(session.questions,session.answers);const history=loadHistory(),growth=roundGrowth(history,session.petId,graded.correct);const record={id:session.id,cardTicket:true,layout:layoutId(session.layout),petId:growth.petId,skin:outfit.skin,growth,grade:session.grade,mode:session.mode,name:session.name,date:new Date().toISOString(),elapsed:Math.round(session.elapsed),...graded};history.unshift(record);if(!storage.write('history',history)){toast('这次成绩暂时没有保存，请重试交卷。');return;}session=null;storage.remove('session');result=record;view='result';showAll=false;renderResult();window.scrollTo({top:0,behavior:'instant'});chime(true);confetti();if(growth.leveledUp)celebratePet(growth.petId);}
function dateLabel(date){return new Date(date).toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});}
function resultTitle(r){return r.accuracy===100?'满星探险，漂亮完成！':r.accuracy>=80?'收获满满，继续闪光！':'认真走到终点，就很棒！';}
function resultTopicSummary(r){const map=new Map();r.details.forEach(q=>{const stat=map.get(q.topic)||{total:0,correct:0};stat.total++;if(q.correct)stat.correct++;map.set(q.topic,stat);});return [...map].map(([t,s])=>`<div class="topic-stat"><span>${escapeHtml(t)}</span><strong>${s.correct} / ${s.total}</strong><div><i style="width:${s.correct/s.total*100}%"></i></div></div>`).join('');}
function renderResult(){
 const r=result,miss=r.details.filter(q=>!q.correct),shown=showAll?r.details:miss;
 app.innerHTML=`<div class="result-intro"><div class="eyebrow"><span></span> ADVENTURE COMPLETE</div><h1>${resultTitle(r)}</h1><p>${escapeHtml(r.name)}，每一次练习，都让你离熟练更近一点。</p></div><section class="result-card"><div class="result-card-head"><span>✦ 学习探险岛 · 探险成绩单</span><span>${dateLabel(r.date)}</span></div><div class="result-main"><div class="score-block"><div class="earned-stars" aria-label="获得 ${r.stars} 颗星星">${[1,2,3].map(n=>`<span class="${n<=r.stars?'earned':''}">★</span>`).join('')}</div><strong>${r.accuracy}<small>%</small></strong><span>本轮正确率</span></div><div class="result-metrics"><div><strong>${r.correct}<small> / ${r.total}</small></strong><span>答对题目</span></div><div><strong>${formatTime(r.elapsed)}</strong><span>实际练习用时</span></div><div><strong>${r.wrong}</strong><span>答错题目</span></div><div><strong>${r.blank}</strong><span>未答题目</span></div></div></div><div class="result-card-bottom"><span>${GRADES[r.grade-1]}年级 · ${displayMode(r.mode,r.grade)} · ${r.total} 题${r.layout&&r.layout!=='sheet'?' · '+LAYOUTS[layoutId(r.layout)].name:''}</span><span>每一步，都算进步。</span></div></section>${rewardCard(r)}${coinReward(r)}${cardUI.ticketPanel(r)}<div class="result-actions"><a id="download-card" class="primary" download="成绩截图.png">下载成绩截图</a>${miss.length?`<button id="retry-wrong" class="secondary">再练 ${miss.length} 道错题</button>`:''}<button id="new-adventure" class="secondary">开启新探险</button><button id="view-history" class="text-btn">查看探险记录</button></div><div class="result-lower"><section class="panel review-panel"><div class="panel-heading"><h2>${showAll?'本轮所有题目':miss.length?'把这些数字，再认识一次':'每一道题，都认真完成了'}</h2><button id="review-toggle" class="text-btn">${showAll?'只看错题':'查看全部题目'}</button></div>${shown.length?`<div class="review-list">${shown.map(q=>reviewRow(q,r.details.indexOf(q)+1)).join('')}</div>`:'<div class="all-correct"><span>✦</span><h3>本轮全对！</h3><p>把这份小小成就保存下来吧。</p></div>'}</section><aside class="panel"><h3>这次学会了什么</h3><div class="topic-stats">${resultTopicSummary(r)}</div><p class="result-tip">答错是发现新知识的机会。先看提示，再试着独立算一遍。</p><details class="card-preview"><summary>成绩截图已生成 · 预览</summary><img id="report-preview" alt="包含成绩、耗时和逐题批改的成绩截图"></details></aside></div>`;
 cardUI.bindTicket(r);document.querySelector('#reward-home')?.addEventListener('click',()=>go('pets'));document.querySelector('#reward-pets')?.addEventListener('click',()=>go('pets'));const downloadLink=document.querySelector('#download-card');downloadLink.download=reportFilename(r);downloadLink.setAttribute('aria-busy','true');document.querySelector('#new-adventure').onclick=()=>go('home');document.querySelector('#view-history').onclick=()=>go('history');document.querySelector('#review-toggle').onclick=()=>{showAll=!showAll;renderResult();};if(miss.length)document.querySelector('#retry-wrong').onclick=()=>startPractice(miss.map(({userAnswer,correct,...q})=>q),r.grade);const reportPreview=document.querySelector('#report-preview');reportPet(r).decode().catch(()=>{}).then(()=>{downloadLink.href=createReport(r);reportPreview.src=createReport(r);downloadLink.removeAttribute('aria-busy');return saveLocalReport(r);}).then(url=>{downloadLink.href=`${url}?download=1&name=${encodeURIComponent(downloadLink.download)}`;}).catch(()=>{});
}
function reviewRow(q,index){return `<div class="review-row ${q.correct?'correct':'incorrect'}"><span class="review-mark">${q.correct?'✓':q.userAnswer.trim()?'×':'·'}</span><div><strong><span class="review-no">${index}.</span> ${escapeHtml(q.expression)}</strong><p>你的答案：<b>${escapeHtml(q.userAnswer)||'未填写'}</b> ${q.correct?'':' · 正确答案：<b>'+q.answer+'</b>'}</p>${q.correct?'':`<p class="explanation">${escapeHtml(q.explanation)}</p>`}</div></div>`;}
function getMistakes(){const last=new Map();for(const r of [...loadHistory()].reverse())for(const q of r.details){const key=`${r.grade}:${q.expression}`;if(q.correct)last.delete(key);else last.set(key,{...q,grade:r.grade,date:r.date});}return [...last.values()].reverse();}
function renderHistory(){
 const history=loadHistory(),shown=historyGrade==='all'?history:history.filter(r=>r.grade===Number(historyGrade)),stars=history.reduce((n,r)=>n+r.stars,0);
 app.innerHTML=`<section class="page-intro"><div><div class="eyebrow"><span></span> YOUR LITTLE ACHIEVEMENTS</div><h1>每一次探险，都有回响。</h1><p>留下练习的足迹，看见一点一点的进步。</p></div><div class="star-balance"><span>★</span><strong>${stars}</strong><small>收集的星星</small></div></section><section class="panel history-panel"><div class="panel-heading"><h2>探险记录 <small>· ${history.length} 次</small></h2><label class="filter-label">年级<select id="history-filter" aria-label="筛选历史年级"><option value="all">全部年级</option>${GRADES.map((g,i)=>`<option value="${i+1}" ${historyGrade===String(i+1)?'selected':''}>${g}年级</option>`).join('')}</select></label></div>${shown.length?`<div class="table-scroll"><table><thead><tr><th>探险时间 / 探险家</th><th>练习内容</th><th>正确率</th><th>用时</th><th>星星</th><th>成绩单</th></tr></thead><tbody>${shown.map(r=>`<tr><td><strong>${dateLabel(r.date)}</strong><small>${escapeHtml(r.name)}</small></td><td>${GRADES[r.grade-1]}年级 · ${displayMode(r.mode,r.grade)}<small>${r.total} 题${r.layout&&r.layout!=='sheet'?' · '+LAYOUTS[layoutId(r.layout)].name:''} · 答对 ${r.correct} 题</small></td><td><span class="score-pill ${r.accuracy===100?'perfect':''}">${r.accuracy}%</span></td><td class="mono">${formatTime(r.elapsed)}</td><td class="mini-stars">${'★'.repeat(r.stars)}</td><td><button class="text-btn open-result" data-record="${escapeHtml(r.id)}">查看</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('⚑',history.length?'这个年级还没有记录':'第一段探险，等你来写','完成一轮练习后，成绩和耗时会自动保存在这里。','出发去练习')}</section><p class="local-note">练习记录保存在此浏览器内。清理浏览器数据会移除记录，重要成绩可以下载图片留存。</p>`;
 document.querySelector('#history-filter').onchange=e=>{historyGrade=e.target.value;renderHistory();};app.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{result=history.find(r=>r.id===b.dataset.record);showAll=false;view='result';renderResult();window.scrollTo({top:0,behavior:'instant'});});app.querySelector('.empty-start')?.addEventListener('click',()=>go('home'));
}
function emptyState(symbol,title,description,label){return `<div class="empty-state"><span>${symbol}</span><h2>${title}</h2><p>${description}</p><button class="primary empty-start">${label}</button></div>`;}
function renderMistakes(){
 const mistakes=getMistakes(),groups=new Map();mistakes.forEach(q=>{const g=groups.get(q.grade)||[];g.push(q);groups.set(q.grade,g);});
 app.innerHTML=`<section class="page-intro"><div><div class="eyebrow"><span></span> ONE MORE TRY</div><h1>错题背包，装着新进步。</h1><p>算错的、漏答的都在这里。再练答对后，它们就会从背包里毕业。</p></div><div class="star-balance"><span>?</span><strong>${mistakes.length}</strong><small>待巩固题目</small></div></section>${mistakes.length?[...groups].map(([g,qs])=>`<section class="panel mistake-group"><div class="panel-heading"><h2>${GRADES[g-1]}年级 · ${qs.length} 道待巩固</h2><button class="primary retry-grade" data-retry-grade="${g}">${qs.length>60?'再练前 60 题':'再练这些题'}</button></div><div class="mistake-grid">${qs.map(q=>`<div class="mistake-item"><strong>${escapeHtml(q.expression)}</strong><span>上次答案：${escapeHtml(q.userAnswer)||'未填写'}</span><details><summary>看看小提示</summary><p>${escapeHtml(q.explanation)}</p><b>正确答案：${q.answer}</b></details></div>`).join('')}</div></section>`).join(''):`<section class="panel">${emptyState('✦','背包轻轻，准备出发','每一道错题都是一个进步机会。完成练习后，需要巩固的题目会自动装进背包。','开始一次探险')}</section>`}`;
 app.querySelectorAll('[data-retry-grade]').forEach(b=>b.onclick=()=>{const g=+b.dataset.retryGrade;startPractice(groups.get(g).slice(0,60).map(({userAnswer,correct,grade,date,...q})=>q),g);});app.querySelector('.empty-start')?.addEventListener('click',()=>go('home'));
}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=document.createElement('div');box.className='confetti';box.setAttribute('aria-hidden','true');box.innerHTML=Array.from({length:35},(_,i)=>`<i style="--x:${Math.random()*100}%;--delay:${Math.random()*.4}s;--rotate:${Math.random()*360}deg;background:${['#ffda76','#12796b','#ed8b42','#88bda2'][i%4]}"></i>`).join('');document.body.append(box);setTimeout(()=>box.remove(),2600);}
const reportPets=Object.fromEntries([...new Set(Object.values(COMPANION_ART).flatMap(art=>art.frames.map(f=>f.src||art.src)))].map(src=>{const image=new Image();image.src=src;return [src,image];}));
function reportPet(r){const art=COMPANION_ART[petId(r.petId)],frame=art.frames[Math.max(0,Math.min(3,(r.growth?.level||1)-1))];return reportPets[frame.src||art.src];}
let reportCache=new Map();
function createReport(r){
 if(reportCache.has(r.id))return reportCache.get(r.id);
 const theme=SKINS[r.skin]||SKINS.green;const columns=2,rows=Math.ceil(r.details.length/columns),canvas=document.createElement('canvas');canvas.width=1200;canvas.height=530+rows*88;const ctx=canvas.getContext('2d');
 ctx.fillStyle=theme.paper;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle=theme.main;ctx.fillRect(0,0,1200,112);ctx.fillStyle='#ffda76';ctx.font='bold 44px sans-serif';ctx.fillText('✦',45,72);ctx.fillStyle='#fff';ctx.font='bold 34px "PingFang SC",sans-serif';ctx.fillText('学习探险岛 · 探险成绩单',104,70);
 ctx.fillStyle=theme.ink;ctx.font='bold 32px "PingFang SC",sans-serif';ctx.fillText(`${r.name} · ${resultTitle(r)}`,50,176);ctx.font='22px "PingFang SC",sans-serif';ctx.fillStyle=theme.muted;ctx.fillText(`${GRADES[r.grade-1]}年级 · ${displayMode(r.mode,r.grade)} · ${r.total} 题 · ${LAYOUTS[layoutId(r.layout)].name}`,50,218);ctx.fillText(new Date(r.date).toLocaleString('zh-CN',{hour12:false}),710,218);if(r.growth){const id=petId(r.petId),image=reportPet(r),frame=COMPANION_ART[id].frames[Math.max(0,Math.min(3,r.growth.level-1))];if(image.complete&&image.naturalWidth){const [x,y,w,h]=frame.window,scale=Math.min(88/w,88/h),dw=w*scale,dh=h*scale;ctx.save();ctx.translate(1050+(88-dw)/2,122+88-dh);ctx.beginPath();frame.clip.slice(8,-1).split(',').forEach((point,i)=>{const [px,py]=point.trim().split(/\s+/).map(parseFloat);ctx[i?'lineTo':'moveTo'](px/100*dw,py/100*dh);});ctx.closePath();ctx.clip();ctx.drawImage(image,x,y,w,h,0,0,dw,dh);ctx.restore();}}
 ctx.fillStyle=theme.tint;ctx.fillRect(40,250,1120,130);ctx.fillStyle=theme.main;ctx.font='bold 60px sans-serif';ctx.fillText(`${r.accuracy}%`,70,324);ctx.font='24px "PingFang SC",sans-serif';ctx.fillStyle=theme.ink;ctx.fillText(`答对 ${r.correct}/${r.total} 题`,300,302);ctx.fillText(`答错 ${r.wrong} 题 · 未答 ${r.blank} 题`,300,346);ctx.fillText(`用时 ${formatTime(r.elapsed)}`,760,302);ctx.fillStyle='#ae862b';ctx.fillText(`获得 ${r.stars} 颗星星`,760,346);
 ctx.fillStyle=theme.ink;ctx.font='bold 24px "PingFang SC",sans-serif';ctx.fillText('逐题批改',50,435);if(r.growth){ctx.font='20px \"PingFang SC\",sans-serif';ctx.fillStyle=theme.main;ctx.fillText(`${PETS[petId(r.petId)].name} +${r.growth.earned} 成长积分 · Lv.${r.growth.level}`,620,435);}
 r.details.forEach((q,i)=>{const col=i%2,row=Math.floor(i/2),x=50+col*565,y=475+row*88;ctx.fillStyle=q.correct?theme.tint:'#fff0e7';ctx.fillRect(x-10,y-24,550,78);ctx.fillStyle=q.correct?theme.main:'#bd4e42';ctx.font='bold 22px "PingFang SC",sans-serif';ctx.fillText(`${q.correct?'✓':'×'} ${i+1}. ${q.expression}`,x,y,510);ctx.font='20px "PingFang SC",sans-serif';ctx.fillStyle='#536e60';ctx.fillText(`你的答案：${q.userAnswer.trim()||'未答'}${q.correct?'':'    正确答案：'+q.answer}`,x+25,y+31,490);});
 ctx.font='20px "PingFang SC",sans-serif';ctx.fillStyle=theme.muted;ctx.fillText('每一步，都算进步。',50,canvas.height-25);const url=canvas.toDataURL('image/png');reportCache.set(r.id,url);if(reportCache.size>10)reportCache.delete(reportCache.keys().next().value);return url;
}
const localReports=new Map();
function reportFilename(r){return `学习探险岛-${r.name}-${r.date.slice(0,10)}-${r.accuracy}分.png`;}
function saveLocalReport(r){if(localReports.has(r.id))return localReports.get(r.id);const pending=fetch('/api/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:r.id,image:createReport(r)})}).then(async response=>{if(!response.ok)throw new Error('保存图片失败');return (await response.json()).url;}).catch(error=>{localReports.delete(r.id);throw error;});localReports.set(r.id,pending);return pending;}
setInterval(()=>{if(session&&view==='practice'&&!session.paused){document.querySelector('#timer').textContent=formatTime(elapsed());checkpoint();}},1000);
window.addEventListener('pagehide',pauseClock);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&view==='practice'&&session){pauseClock();renderPractice();}});
window.addEventListener('pageshow',()=>{if(view==='practice'&&session)renderPractice();});
updateSound();renderHome();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [
 {name:'read_practice_summary',title:'查看口算练习概况',description:'读取当前本地练习进度与历史概要，不包含答案。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view,unfinished:session?{grade:session.grade,total:session.questions.length,filled:session.answers.filter(a=>a.trim()).length,elapsedMs:Math.round(elapsed())}:null,completed:loadHistory().map(r=>({id:r.id,grade:r.grade,accuracy:r.accuracy,elapsedMs:r.elapsed}))})},
 {name:'start_math_practice',title:'开始新的口算练习',description:'按年级与题型开启本地口算练习；已有未完成练习时拒绝替换。',inputSchema:{type:'object',properties:{grade:{type:'integer',minimum:1,maximum:6},mode:{type:'string',enum:['mixed','addsub','multiply','missing']},count:{type:'integer',enum:[20,30,60]}},required:['grade','mode','count'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(session)throw new Error('请先在页面处理未完成的练习');if(!input||![20,30,60].includes(input.count))throw new Error('题量不正确');const qs=generateQuestions(input);grade=input.grade;mode=input.mode;count=input.count;savePrefs();startPractice();return {grade,total:qs.length,view};}}
 ]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
